// pt.json and it.json are generated by tool/gen_romance_transforms.dart. A hand
// edit to either JSON would be lost on the next run of the generator, and a
// generator change that was never run would ship stale rules, so the checked-in
// files must match its output byte for byte.
//
// The lookup behaviour itself is covered by the native
// romance_inflection_lookup_test.
import 'dart:convert';
import 'dart:io';

import 'package:flutter_test/flutter_test.dart';

import '../../tool/gen_romance_transforms.dart' as gen;

void main() {
  const String dir = 'assets/transforms';

  for (final gen.TransformTable table in <gen.TransformTable>[
    gen.portuguese(),
    gen.italian(),
  ]) {
    test('${table.language}.json matches the generator', () {
      final File file = File('$dir/${table.language}.json');
      expect(file.existsSync(), isTrue, reason: 'missing ${file.path}');
      expect(
        file.readAsStringSync(),
        '${table.encode()}\n',
        reason:
            'Regenerate with `dart run tool/gen_romance_transforms.dart` '
            '(from fushi/) instead of editing the JSON by hand.',
      );
    });
  }

  test('manifest lists pt and it', () {
    final List<dynamic> manifest =
        jsonDecode(File('$dir/manifest.json').readAsStringSync())
            as List<dynamic>;
    expect(manifest, containsAll(<String>['pt', 'it']));
  });
}
